```tsx
import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps) {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button type="button" className="alert-banner__retry" onClick={onRetry}>
        Retry
      </button>
    </div>
  );
}
```

```css
.alert-banner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  padding: clamp(0.6rem, 1.2vw, 0.9rem) clamp(0.8rem, 1.6vw, 1.1rem);
  border-left: 3px solid var(--ink);
  border-radius: 6px;
  background: var(--code-bg);
  color: var(--ink);
  font: inherit;
}

.alert-banner__message {
  margin: 0;
  flex: 1 1 16rem;
  font-size: clamp(0.9rem, 1.4vw, 1rem);
  line-height: 1.4;
  color: var(--ink);
}

.alert-banner__retry {
  flex: 0 0 auto;
  padding: 0.4rem 0.9rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.85rem, 1.3vw, 0.95rem);
  cursor: pointer;
}

.alert-banner__retry:hover {
  background: var(--myelin-wash);
  border-color: var(--myelin);
}

/* Focus outline comes from the global :focus-visible rule; this only adds to it. */
.alert-banner__retry:focus-visible {
  border-color: var(--myelin);
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__retry {
    transition: none;
  }
}

:root[data-motion="reduce"] .alert-banner__retry {
  transition: none;
}
```

